const D = (u, v, c, lab, r) => ({ t: "dot", u, v, c, lab, r });
const RG = (u, v, r, c, lab, solid) => ({ t: "ring", u, v, r, c, lab, solid });
const LN = (u1, v1, u2, v2, c, o = {}) => ({ t: "line", u1, v1, u2, v2, c, ...o });
const CH = (u, v, text, c) => ({ t: "chip", u, v, text, c });
const BX = (u, v, w, h, c, lab) => ({ t: "box", u, v, w, h, c, lab });
const OL = (u, v, w, h, c, lab) => ({ t: "outline", u, v, w, h, c, lab });
const RB = (u, v, w, h, deg, c, lab) => ({ t: "rbox", u, v, w, h, deg, c, lab });
const ST = (u, v, len, deg, c, lab) => ({ t: "stick", u, v, len, deg, c, lab });
const TX = (u, v, text, c) => ({ t: "text", u, v, text, c });
const WALLS = [BX(0, 0, 1, 0.025, "MUTED"), BX(0, 0.975, 1, 0.025, "MUTED"), BX(0, 0, 0.015, 1, "MUTED"), BX(0.985, 0, 0.015, 1, "MUTED")];
// 5×5 격자: 칸 [열, 행]
const GRID = ({ a, g, walls = [], path = [] }) => {
  const out = [];
  for (let r = 0; r < 5; r++) for (let c = 0; c < 5; c++) {
    const key = `${c},${r}`;
    let col = "CARD2";
    if (walls.includes(key)) col = "NEG";
    if (g && key === g.join(",")) col = "POS";
    out.push(BX(0.2 + c * 0.12 + 0.006, 0.08 + r * 0.168 + 0.008, 0.108, 0.152, col));
    if (path.includes(key)) out.push(D(0.26 + c * 0.12, 0.164 + r * 0.168, "MUTED", null, 0.025));
  }
  if (a) out.push(BX(0.2 + a[0] * 0.12 + 0.02, 0.08 + a[1] * 0.168 + 0.025, 0.08, 0.118, "ACC"));
  return out;
};
const STEPS = (max) => Array.from({ length: 11 }, (_, i) => String(Math.round((max * i) / 10)));
const ARM = (a1, a2, btn, hit) => {
  // 받침 (0.5, 0.56), 링크 0.22 · 0.16 (짧은 변 기준), 가로세로비 약 1.4
  const bu = 0.5, bv = 0.56, s = 1 / 1.4, r = (d) => (d * Math.PI) / 180;
  const ju = bu + 0.22 * Math.cos(r(a1)) * s, jv = bv + 0.22 * Math.sin(r(a1));
  const tu = ju + 0.16 * Math.cos(r(a1 + a2)) * s, tv = jv + 0.16 * Math.sin(r(a1 + a2));
  const btu = bu + 0.28 * Math.cos(r(btn)) * s, btv = bv + 0.28 * Math.sin(r(btn));
  return [RG(bu, bv, 0.38, "MUTED"), RG(bu, bv, 0.1, "MUTED"), D(btu, btv, "POS", "버튼", 0.05),
    LN(bu, bv, ju, jv, "ENV", { wd: 6 }), LN(ju, jv, tu, tv, "ENV", { wd: 4 }), D(bu, bv, "TEXT", null, 0.05), D(tu, tv, hit ? "POS" : "ACC", "팔 끝", 0.035)];
};

